import { cancelBubble, d } from '@cetus/utils'
import { ChangeEvent } from 'react'
import { InputAttributes, NumericFormat, NumericFormatProps } from 'react-number-format'

interface NumericFormatInputParams extends Omit<NumericFormatProps<InputAttributes>, 'onChange'> {
  value: string
  decimals?: number
  placeholder?: string
  maxValue?: number
  minValue?: number
  inputAllowed?: boolean
  prefix?: string
  style?: Record<string, string | number>
  onChange: (value: string) => void
}

export default function NumericFormatInput(props: NumericFormatInputParams) {
  const { value, decimals, placeholder, style, onChange, maxValue, minValue = 0, inputAllowed = true, prefix, ...rest } = props

  const handleChange = (e: ChangeEvent<HTMLInputElement> | undefined) => {
    const inputValue = e?.target?.value
    if (inputValue) {
      if (inputValue.startsWith('.')) {
        onChange(inputValue.slice(1, inputValue.length))
        return
      }

      // if (inputValue === '0.') {
      //   onChange('0.')
      //   return
      // }

      try {
        if (d(inputValue).eq(0)) {
          onChange('0')
          return
        }
      } catch (error) {
        console.log('🚀 ~ handleChange ~ error:', error)
      }

      let numericValue =
        inputValue
          .replace(/^0+$/, '0') // 如果整个字符串是零，返回 '0'
          .replace(/^0+(?!\.\d+$)/g, '') // 去除前导零，保留小数部分的零
          .replace(/,/g, '') || '' // 去除逗号，空值保持为空

      if (numericValue.startsWith('-')) {
        onChange('')
        return
      }
      if (prefix) {
        numericValue = numericValue.replace(prefix, '')
      }
      if (maxValue !== undefined && d(numericValue).gt(maxValue)) {
        numericValue = maxValue.toString()
      } else if (minValue !== undefined && d(numericValue).lt(minValue)) {
        numericValue = minValue.toString()
      }
      onChange(String(numericValue))
    } else {
      onChange('')
    }
  }

  return (
    <NumericFormat
      value={value}
      disabled={!inputAllowed}
      placeholder={placeholder}
      decimalScale={decimals}
      prefix={prefix}
      allowLeadingZeros
      thousandSeparator=","
      onMouseDown={e => {
        cancelBubble(e)
      }}
      isAllowed={value => {
        return !value.value.startsWith('-')
      }}
      onChange={handleChange}
      {...rest}
      style={{
        ...style,
        cursor: inputAllowed ? 'text' : 'not-allowed',
        fontFamily:
          '-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,Noto Sans,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji',
        fontFeatureSettings: 'tnum',
        fontVariant: 'tabular-nums'
      }}
    />
  )
}
